-- Include account-scoped historical usage with NULL venue; no rows are changed.
DROP TRIGGER qa_pos_pause_usage_insert;
DROP TRIGGER qa_pos_pause_usage_update;
DROP TRIGGER qa_pos_pause_usage_delete;
CREATE TRIGGER qa_pos_pause_usage_insert BEFORE INSERT ON ai_usage_events WHEN (NEW.venue_id=3389 OR NEW.account_id=148) AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
CREATE TRIGGER qa_pos_pause_usage_update BEFORE UPDATE ON ai_usage_events WHEN (OLD.venue_id=3389 OR OLD.account_id=148 OR NEW.venue_id=3389 OR NEW.account_id=148) AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
CREATE TRIGGER qa_pos_pause_usage_delete BEFORE DELETE ON ai_usage_events WHEN (OLD.venue_id=3389 OR OLD.account_id=148) AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;

